{
  "cvars": {
    "ivs": [
      {
        "description": "Student-teacher ratio measured as number of students per full-time-equivalent teacher. Lower values indicate fewer students per teacher (a smaller class size / better staffing). This is the main independent variable of interest.",
        "columns": [
          "students_per_teacher"
        ]
      }
    ],
    "dv": {
      "description": "District-level average academic performance, computed as the mean of the 5th-grade Stanford-9 reading and math scores.",
      "columns": [
        "AvgScore"
      ]
    },
    "controls": [
      {
        "description": "Expenditure per student (district spending per pupil). Controls for resource intensity.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "expenditure"
        ]
      },
      {
        "description": "District average household income (in thousands of USD). Controls for socioeconomic status.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "income"
        ]
      },
      {
        "description": "Percent of students qualifying for reduced-price lunch (proxy for poverty).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "lunch"
        ]
      },
      {
        "description": "Percent of English learners in the district.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "english"
        ]
      },
      {
        "description": "Number of computers per student (computers divided by students). Controls for technology access.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "computers_per_student"
        ]
      },
      {
        "description": "Percent qualifying for CalWorks (income assistance). Additional poverty control.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "calworks"
        ]
      },
      {
        "description": "Indicator for district grade span KK-08 (1 = 'KK-08', 0 = 'KK-06'). Controls for grade configuration differences.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "grades_KK08"
        ]
      },
      {
        "description": "Total district enrollment (student body size). Controls for district size effects.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "students"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Work on a copy\n    df = df.copy()\n\n    # Ensure numeric columns are numeric\n    numeric_cols = ['students', 'teachers', 'computer', 'expenditure', 'income', 'calworks', 'lunch', 'english', 'read', 'math']\n    for c in numeric_cols:\n        if c in df.columns:\n            df[c] = pd.to_numeric(df[c], errors='coerce')\n\n    # Drop rows missing core variables needed for analysis\n    df = df.dropna(subset=['students', 'teachers', 'read', 'math'])\n\n    # Remove rows with non-positive teachers to avoid division by zero\n    df = df[df['teachers'] > 0]\n\n    # Compute student-teacher ratio (students per teacher)\n    df['students_per_teacher'] = df['students'] / df['teachers']\n\n    # Compute computers per student (handle division by zero defensively)\n    df['computers_per_student'] = df['computer'] / df['students']\n\n    # Compute the dependent variable: average of reading and math scores\n    df['AvgScore'] = df[['read', 'math']].mean(axis=1)\n\n    # Create a binary indicator for grades span (KK-08 vs KK-06)\n    # If grades is missing, set to 0 (will have been dropped earlier if core vars missing)\n    df['grades_KK08'] = (df['grades'].astype(str) == 'KK-08').astype(int)\n\n    # Optional: winsorize extreme student-teacher ratios to reduce influence of outliers\n    # Clip at 1st and 99th percentiles\n    if 'students_per_teacher' in df.columns:\n        lower = df['students_per_teacher'].quantile(0.01)\n        upper = df['students_per_teacher'].quantile(0.99)\n        df['students_per_teacher'] = df['students_per_teacher'].clip(lower=lower, upper=upper)\n\n    # Ensure control columns exist (if missing, create as NaN so downstream code can handle/drop)\n    for col in ['expenditure', 'income', 'lunch', 'english', 'calworks', 'students', 'computers_per_student']:\n        if col not in df.columns:\n            df[col] = np.nan\n\n    # Final drop: remove any rows missing the dependent or the primary independent variable\n    df = df.dropna(subset=['AvgScore', 'students_per_teacher'])\n\n    # Return the transformed dataframe containing all columns used in modeling\n    return df\n",
  "m_code": "def model(df: pd.DataFrame):\n    # Copy to avoid modifying original\n    df = df.copy()\n\n    # Columns to include in the regression\n    X_cols = [\n        'students_per_teacher',\n        'expenditure',\n        'income',\n        'lunch',\n        'english',\n        'computers_per_student',\n        'calworks',\n        'grades_KK08',\n        'students'\n    ]\n\n    # Keep only rows with no missing values on model predictors (or alternatively drop/ impute as needed)\n    df_model = df.dropna(subset=X_cols + ['AvgScore'])\n\n    # Design matrix\n    X = df_model[X_cols].astype(float)\n    X = sm.add_constant(X)\n    y = df_model['AvgScore'].astype(float)\n\n    # Fit OLS with heteroskedasticity-robust standard errors (HC3)\n    model_res = sm.OLS(y, X).fit(cov_type='HC3')\n\n    # Return the fitted results object. The caller can inspect model_res.summary(), model_res.params, etc.\n    return model_res\n"
}
